            WHEN app_user.deletion_state = 'active' AND app_user.disabled_at IS NULL
              THEN now()
            ELSE app_user.last_authenticated_at
          END
        RETURNING
          app_user_id,
          auth_subject,
          display_name,
          application_role,
          submitter_approval_state,
          disabled_at,
          deletion_state
      ),
      resolved_account AS (
