import { Client } from 'pg';

import { synchronizeApplicationAccount } from '../src/modules/accounts/account.repository';

async function diagnose(): Promise<void> {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  try {
    await client.query('BEGIN READ WRITE');

    const existingAccount = await client.query<{
      auth_provider: string;
      auth_subject: string;
      display_name: string | null;
    }>(
      `
        SELECT auth_provider, auth_subject, display_name
        FROM app_user
        WHERE auth_provider = 'supabase'
        ORDER BY app_user_id
        LIMIT 1
      `,
    );
    const row = existingAccount.rows[0];

    if (!row) {
      throw new Error('No existing Supabase application account is available for diagnosis.');
    }

    const account = await synchronizeApplicationAccount(
      { uid: row.auth_subject, displayName: row.display_name },
      client,
    );

    console.log({
      role: account.role,
      approvalState: account.approvalState,
      competitionCount: account.competitionIds.length,
      disabled: account.disabled,
      deletionState: account.deletionState,
    });
  } finally {
    await client.query('ROLLBACK');
    await client.end();
  }
}

diagnose().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : 'Unknown diagnosis failure.');
  process.exitCode = 1;
});

