      approvalState: account.approvalState,
      competitionCount: account.competitionIds.length,
      disabled: account.disabled,
      deletionState: account.deletionState,
    });
  } finally {
    await client.query('ROLLBACK');
    await client.end();
  }
}

diagnose().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : 'Unknown diagnosis failure.');
  process.exitCode = 1;
});

