import type {
  ApiErrorDetail,
  CurrentUserProfile,
  Fixture,
  SubmissionResponse,
} from '@sport-analytics/contracts';
import { useEffect, useRef, useState } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { ApiResponseError } from '../../api/client';
import { useAuth } from '../auth/AuthProvider';
import { getCurrentUserProfile } from '../auth/current-user-api';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import { listScopedFixtures, SubmissionInputError, submitEvents } from './submission-api';

const EMPTY_EVENTS = '[]';

type AccessState =
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | {
      kind: 'forbidden';
      role: CurrentUserProfile['role'];
      approvalState: CurrentUserProfile['approvalState'];
    }
  | { kind: 'permitted'; fixtures: Fixture[] };

type ResultState =
  | { kind: 'idle' }
  | { kind: 'submitting' }
  | { kind: 'accepted'; response: SubmissionResponse }
  | { kind: 'rejected'; message: string; details: ApiErrorDetail[] }
  | { kind: 'error'; message: string };

function usePageTitle() {
  useEffect(() => {
    document.title = "Submit Events | Stat'sTheGame";
  }, []);
}

function formatFixtureOption(fixture: Fixture): string {
  return `${fixture.startDate} â€” ${fixture.matchType}, ${fixture.season} (fixture ${fixture.fixtureId})`;
}

function formatValidationLocation(detail: ApiErrorDetail): string {
  const eventLabel =
    detail.eventIndex === undefined ? 'Submission' : `Event ${detail.eventIndex + 1}`;
  let field = detail.field;

  if (field && detail.eventIndex !== undefined) {
    field = field.replace(new RegExp(`^events\\.${detail.eventIndex}\\.?`), '');
  }

  return field ? `${eventLabel} â€” ${field}` : eventLabel;
}

function AccessError({ message }: { message: string }) {
  return (
    <div className="state-message state-message--error" role="alert">
      <h2>Submission access could not be checked</h2>
      <p>{message}</p>
    </div>
  );
}

function ForbiddenState({
  role,
  approvalState,
}: {
  role: CurrentUserProfile['role'];
  approvalState: CurrentUserProfile['approvalState'];
}) {
  const detail =
    role === 'viewer' && approvalState === 'pending'
      ? 'Your submitter request is pending approval.'
      : 'Your account does not have the submitter role required to submit event data.';

  return (
    <div className="state-message" role="status">
      <h2>Submitter role required</h2>
      <p>{detail} The backend will continue to protect every submission and competition scope.</p>
      <Link className="button button--secondary" to="/account">
        Return to account
      </Link>
    </div>
  );
}

function ValidationResults({ message, details }: { message: string; details: ApiErrorDetail[] }) {
  return (
    <div className="submission-result submission-result--error" role="alert">
      <h2 tabIndex={-1} data-result-heading>
        Submission rejected
      </h2>
      <p>{message}</p>
      {details.length > 0 ? (
        <ol className="validation-results">
          {details.map((detail, index) => (
            <li
              key={`${detail.code}-${detail.eventIndex ?? 'submission'}-${detail.field ?? index}`}
            >
              <strong>{formatValidationLocation(detail)}</strong>
              <span>{detail.message}</span>
            </li>
          ))}
        </ol>
      ) : null}
    </div>
  );
}

function SubmissionForm({ fixtures }: { fixtures: Fixture[] }) {
  const client = useAuthenticatedApiClient();
  const [fixtureId, setFixtureId] = useState(fixtures[0]?.fixtureId ?? '');
  const [eventJson, setEventJson] = useState(EMPTY_EVENTS);
  const [result, setResult] = useState<ResultState>({ kind: 'idle' });
  const resultRegionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (result.kind === 'accepted' || result.kind === 'rejected' || result.kind === 'error') {
      resultRegionRef.current?.querySelector<HTMLElement>('[data-result-heading]')?.focus();
    }
  }, [result]);

  function resetResult() {
    if (result.kind !== 'idle' && result.kind !== 'submitting') {
      setResult({ kind: 'idle' });
    }
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setResult({ kind: 'submitting' });

    try {
      const response = await submitEvents(client, fixtureId, eventJson);
      setResult({ kind: 'accepted', response });
    } catch (error) {
      if (error instanceof SubmissionInputError) {
        setResult({ kind: 'rejected', message: error.message, details: [] });
      } else if (error instanceof ApiResponseError && error.details) {
SUBMISSION SERVICE
import type { SubmissionRequest, SubmissionResponse } from '@sport-analytics/contracts';

import { hasCompetitionScope } from '../../middleware/require-authorization';
import type { ApplicationAccount } from '../accounts/account';
import { SubmissionForbiddenError, SubmissionValidationError } from './submission.errors';
import { createSubmissionRepository, type SubmissionRepository } from './submission.repository';

export interface SubmissionService {
  submit(account: ApplicationAccount, submission: SubmissionRequest): Promise<SubmissionResponse>;
}

export function createSubmissionService(
  repository: SubmissionRepository = createSubmissionRepository(),
): SubmissionService {
  return {
    async submit(account, submission) {
      const fixture = await repository.findFixtureScope(submission.fixtureId);
      if (!fixture) {
        throw new SubmissionValidationError('The submission references an unavailable fixture.', [
          {
            code: 'FIXTURE_NOT_FOUND',
            message: 'The fixture does not exist.',
            field: 'fixtureId',
          },
        ]);
      }

      if (!fixture.competitionId || !hasCompetitionScope(account, fixture.competitionId)) {
        throw new SubmissionForbiddenError();
      }

      // The dismissal vocabulary is held in the dismissal_kind lookup table, not
      // enumerated in the contract, because the set is open. Resolving it here
      // rather than relying on the foreign key means an unrecognised kind is
      // rejected with the field and the value that caused it, instead of
      // surfacing as an unexplained server error.
      const submittedWickets = submission.events.flatMap((event, eventIndex) =>
        event.wickets.map((wicket) => ({ eventIndex, kind: wicket.kind })),
      );

      if (submittedWickets.length > 0) {
        const recognisedKinds = await repository.findDismissalKinds();
        const unrecognised = submittedWickets.filter((wicket) => !recognisedKinds.has(wicket.kind));

        if (unrecognised.length > 0) {
          throw new SubmissionValidationError(
            'The submission references a dismissal kind the platform does not recognise.',
            unrecognised.map((wicket) => ({
              code: 'UNKNOWN_DISMISSAL_KIND',
              message: `"${wicket.kind}" is not a recognised dismissal kind.`,
              field: 'wickets.kind',
              eventIndex: wicket.eventIndex,
            })),
          );
        }
      }

      const acceptedSubmission = await repository.storeAcceptedSubmission(
        submission,
        account.accountId,
      );

      return {
        data: acceptedSubmission,
      };
    },
  };
}
AUTHORIZATION MIDDLEWARE
import type { Request, RequestHandler, Response } from 'express';
import type { ApplicationAccount } from '../modules/accounts/account';
import { rejectAuthorization } from './authorization-response';

type CompetitionIdResolver = (request: Request) => string | undefined | Promise<string | undefined>;

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Authorization middleware requires an authenticated application account');
  }

  return account;
}

export function requireAdministrator(): RequestHandler {
  return (_request, response, next) => {
    let account: ApplicationAccount;

    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    if (account.role !== 'admin') {
      rejectAuthorization(response);
      return;
    }

    next();
  };
}

export function requireSubmitter(): RequestHandler {
  return (_request, response, next) => {
    let account: ApplicationAccount;

    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    if (account.role !== 'submitter' && account.role !== 'admin') {
      rejectAuthorization(response);
      return;
    }

    next();
  };
}

export function hasCompetitionScope(account: ApplicationAccount, competitionId: string): boolean {
  return account.competitionIds.includes(competitionId);
}

export function requireCompetitionScope(
  resolveCompetitionId: CompetitionIdResolver,
): RequestHandler {
  return async (request, response, next) => {
    try {
      const account = getAuthenticatedAccount(response);
      const competitionId = await resolveCompetitionId(request);

      if (!competitionId) {
        throw new Error('Competition-scope authorization requires a competition identifier');
      }

      if (!hasCompetitionScope(account, competitionId)) {
        rejectAuthorization(response);
        return;
      }

      next();
    } catch (error) {
      next(error);
    }
  };
}
